import com.github.benmanes.caffeine.cache.Cache;
import com.github.benmanes.caffeine.cache.Caffeine;
import java.util.concurrent.TimeUnit;

public class ProductCatalogService {
    private final Cache<String, Product> productCache = Caffeine.maximumSize(10_000)
        .expireAfterWrite(10, TimeUnit.MINUTES)
        .recordStats()
        .build();

    public Product getProduct(String sku) {
        return productCache.get(sku, this::fetchProductFromDatabase);
    }

    private Product fetchProductFromDatabase(String sku) {
        // Expensive SQL query or remote network call
        return databaseClient.queryBySku(sku);
    }
}
